import json
from pathlib import Path
A=[]
def add(i,s,q,m,c='material',stage='recognized',**kw):A.append(dict(index=i,classification=c,summary=s,rows=[dict(quote=q,model_quantity=m,stage=stage,issuer_treatment=s,**kw)]))
add(158,'En 2025, revenu HPC de 16,9 M$ sous ASC 842, comprenant énergie et fit-out refacturés ; coûts de revenu hors amortissements. Un seul client HPC déclaré, sans nom attaché au ratio. Cash libre de 3,266389 Md$ et cash restreint de 456,386 M$ séparés. Les ventes bitcoin deviennent flux d’investissement après juillet 2024. Abernathy est une VIE non consolidée ; les warrants Google constituent un passif de juste valeur, sans paiement cash identique.','Variable lease payments are presented on a gross basis and are included in HPC lease revenue in the consolidated statements of operations.','hpc_revenue_gross_variable_power_and_fitout',counterparty_evidence='anonymous',measurement_basis='FY2025_ASC842_16_899m;gross_power;cost_excludes_depreciation')
add(159,'Fin 2025 : 18 MW IT HPC effectivement énergisés contre 245 MW minage ; les ambitions cloud ne prouvent pas un service cloud déjà vendu. Beowulf E&D est acquis à 100 %, pour une contrepartie totale en juste valeur de 54,6 M$ incluant actions et compléments conditionnels, distincte du cash initial de 3 M$. Nautilus est cédé depuis octobre 2024.','had energized 18 critical IT MW of HPC leasing capacity','hpc_energized_capacity_not_pipeline',stage='delivered')
add(160,'Abernathy : 450 M$ cash versés pour 50,1 %, sans consolidation car absence de pouvoir déterminant. TeraWulf doit couvrir les apports supplémentaires que Fluidstack choisit de ne pas faire ; option de rachat Fluidstack après mise en service. Les 1,3 Md$ de notes JV restent une dette de la JV. Nautilus cédé en 2024 pour 102,1 M$ comprend seulement 86,1 M$ cash, plus bitcoin et équipements ; clause de partage d’une revente future conditionnelle.','with the TeraWulf Member being required to contribute any shortfall that the Fluidstack Member elects not to contribute','joint_venture_partner_capital_shortfall_obligation',stage='signed',counterparty='Fluidstack',counterparty_evidence='named',measurement_basis='Abernathy_50_1percent_equity_method;mandatory_shortfall_funding;no_quantified_cap',judgment_sensitive=True)
add(161,'Aucun litige matériel déclaré à fin 2025. Cette note de litiges ne constitue pas un inventaire nul des engagements de construction, des garanties ou des apports JV, décrits ailleurs.','The Company is not a party to any material legal proceedings','no_material_litigation_disclosed_not_zero_commitments',c='context')
add(162,'Hawesville acquis le 2 février 2026 ; minoritaire vendeur à 6,8 % avec droit de remboursement après début des opérations et, initialement, sans obligation d’apport. Morgantown est signé mais reste soumis aux consentements et autorisations : acquisition prévue, pas clôture établie dans ce dépôt. Aucun nouveau client HPC nommé par ces acquisitions.','The closing of the Morgantown acquisition is subject to certain third-party consents and customary regulatory approvals','subsequent_site_acquisition_closing_conditions',stage='signed')
add(163,'Exercice 2025 : HPC 16,899 M$ de revenu et 7,082 M$ de profit segment, minage 151,556 M$. Le profit segment HPC exclut notamment amortissements et frais centraux ; il ne mesure ni résultat net ni cash disponible pour la dette. La perte de 429,793 M$ sur warrants/dérivés est distincte du paiement cash des coupons.','Cost of revenue (exclusive of depreciation)','segment_profit_excludes_depreciation_and_financing',measurement_basis='FY2025_HPC_16_899m_revenue_7_082m_segment_profit;not_cash_margin')
add(164,'Fin 2025 : passif warrants Google de 844,698 M$ et perte annuelle de réévaluation de 329,2 M$, non cash et distincts de l’actif initial de soutien de 515,5 M$. Valorisation niveau 3 sensible à la volatilité ; juste valeur des notes ne correspond pas à leur principal ni au montant de soutien Google.','The Company recognized a loss of $329.2 million during the year ended December 31, 2025','google_warrant_remeasurement_non_cash',counterparty='Google',counterparty_evidence='named',judgment_sensitive=True)
Path(__file__).with_suffix('.json').write_text(json.dumps(A,ensure_ascii=False,indent=2)+'\n')
M=json.loads(Path('work/continuation398/scope.json').read_text())['rows']
for a in A:
 t=json.loads(Path(M[a['index']]['path']).read_text())['text']
 for r in a['rows']:assert r['quote'] in t,(a['index'],r['quote'])
